create extension if not exists "uuid-ossp";
create table if not exists app_users(id uuid primary key default uuid_generate_v4(),email text unique not null,password_hash text not null,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists leaders(id uuid primary key default uuid_generate_v4(),name text not null,contact_name text,phone text,wechat text,platform text not null check(platform in('jd','douyin','tmall')),province text,city text,district text,address text,longitude numeric(10,7),latitude numeric(10,7),cooperation_status text not null default '合作中',tags text[] not null default '{}',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists talents(id uuid primary key default uuid_generate_v4(),name text not null,platform text not null check(platform in('jd','douyin','tmall')),platform_account text,phone text,wechat text,leader_id uuid references leaders(id) on delete set null,province text,city text,district text,address text,longitude numeric(10,7),latitude numeric(10,7),location_precision text,cooperation_status text not null default '合作中',tags text[] not null default '{}',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(platform,platform_account));
create table if not exists products(id uuid primary key default uuid_generate_v4(),external_product_id text unique,name text not null,model_family text,size text,created_at timestamptz not null default now());
create table if not exists import_jobs(id uuid primary key default uuid_generate_v4(),channel text not null check(channel in('jd','douyin','tmall')),file_name text not null,file_hash text,status text not null default 'processing',total_rows integer not null default 0,inserted_rows integer not null default 0,updated_rows integer not null default 0,skipped_rows integer not null default 0,error_rows integer not null default 0,date_min timestamptz,date_max timestamptz,created_by uuid references app_users(id) on delete set null,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists orders(id uuid primary key default uuid_generate_v4(),platform text not null check(platform in('jd','douyin','tmall')),source_key text not null,order_no text not null,external_product_id text,merchant_code text,quantity integer not null check(quantity>0),paid_at timestamptz not null,order_status text not null,payable_amount numeric(14,2) not null check(payable_amount>=0),talent_name_raw text not null,is_talent boolean not null default true,product_name_raw text,model_name text,talent_id uuid references talents(id) on delete set null,product_id uuid references products(id) on delete set null,import_job_id uuid references import_jobs(id) on delete set null,source_payload jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(platform,source_key));
create table if not exists product_mapping_uploads(id uuid primary key default uuid_generate_v4(),channel text not null check(channel in('jd','douyin','tmall')),file_name text not null,row_count integer not null default 0,active boolean not null default true,created_by uuid references app_users(id) on delete set null,created_at timestamptz not null default now());
create table if not exists product_mappings(id uuid primary key default uuid_generate_v4(),upload_id uuid not null references product_mapping_uploads(id) on delete cascade,channel text not null check(channel in('jd','douyin','tmall')),merchant_code text not null,promotion_name text not null,model_name text,created_at timestamptz not null default now(),unique(upload_id,merchant_code));
create unique index if not exists product_mapping_one_active_upload_idx on product_mapping_uploads(channel) where active;
create index if not exists orders_platform_paid_at_idx on orders(platform,paid_at);
create index if not exists orders_douyin_analytics_idx on orders(platform,is_talent,paid_at);
create index if not exists orders_model_name_idx on orders(model_name);
create index if not exists talents_platform_idx on talents(platform);
create index if not exists leaders_platform_idx on leaders(platform);
